baseCss:
.aha-comparison{
  container:aha-comparison / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-comparison *{box-sizing:border-box}
.aha-comparison--accent{box-shadow:inset 0 0 0 100vmax var(--aha-bg-accent)}
:where(.aha-comparison) :is(h2,p,table){margin:0;padding:0}
.aha-comparison__inner{--aha-web-gutter:var(--aha-space-64);max-width:1280px;margin:0 auto;padding:var(--aha-space-96) var(--aha-web-gutter)}
.aha-comparison__header{max-width:720px;margin:0 auto var(--aha-space-64);text-align:center}
.aha-comparison__eyebrow{margin:0 0 var(--aha-space-16);font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-comparison__title{font-size:var(--aha-size-h2);line-height:var(--aha-line-height-heading);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-headlines);color:var(--aha-text-default)}
.aha-comparison__lead{max-width:44ch;margin:var(--aha-space-20) auto 0;font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-comparison__sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-comparison__table-wrap{position:relative;width:100%;border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-default);background:var(--aha-white)}
.aha-comparison__table-wrap:focus-visible{outline:var(--aha-space-2) solid var(--aha-color-primary);outline-offset:var(--aha-space-2)}
.aha-comparison__table{width:100%;border-collapse:separate;border-spacing:0;table-layout:fixed;text-align:center}
.aha-comparison__table caption{position:absolute}
.aha-comparison__label-col{width:32%}
.aha-comparison__table thead :is(th,td){padding:var(--aha-space-24) var(--aha-space-16);vertical-align:bottom}
.aha-comparison__column-head aha-tag{display:block;width:fit-content;margin:var(--aha-space-8) auto 0}
.aha-comparison__column-name{display:block;font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-comparison__column-text{display:block;margin-top:var(--aha-space-8);font-size:var(--aha-size-sm);line-height:var(--aha-line-height-body);font-weight:var(--aha-weight-regular);color:var(--aha-text-secondary)}
.aha-comparison__group th{padding:var(--aha-space-24) var(--aha-space-16) var(--aha-space-8);text-align:left;font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-comparison__table tbody tr:not(.aha-comparison__group) :is(th,td){height:var(--aha-space-60);padding:var(--aha-space-8) var(--aha-space-16);border-top:1px solid var(--aha-border-default);font-size:var(--aha-size-default);color:var(--aha-text-secondary);vertical-align:middle}
.aha-comparison__table tbody tr:not(.aha-comparison__group) th{text-align:left;font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-comparison__table tbody tr:not(.aha-comparison__group):hover :is(th,td){background:var(--aha-gray-30)}
.aha-comparison__mark{vertical-align:middle}
.aha-comparison__mark--yes{color:var(--aha-color-primary)}
.aha-comparison__mark--no{color:var(--aha-icon-muted)}
.aha-comparison__table .aha-comparison__col--highlight{box-shadow:inset var(--aha-space-2) 0 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary)}
.aha-comparison__table thead .aha-comparison__col--highlight{border-radius:var(--aha-radius-default) var(--aha-radius-default) 0 0;box-shadow:inset var(--aha-space-2) var(--aha-space-2) 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary)}
.aha-comparison__table .aha-comparison__col--last{border-radius:0 0 var(--aha-radius-default) var(--aha-radius-default);box-shadow:inset var(--aha-space-2) 0 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary),inset 0 calc(-1 * var(--aha-space-2)) 0 var(--aha-color-primary)}
.aha-comparison__cta{display:flex;justify-content:center;margin-top:var(--aha-space-48)}
@container aha-comparison (max-width:767px){
  .aha-comparison__inner{--aha-web-gutter:var(--aha-space-24);padding:var(--aha-space-48) var(--aha-web-gutter)}
  .aha-comparison__header{margin-bottom:var(--aha-space-40)}
  .aha-comparison__label-col{width:36%}
  .aha-comparison__table thead :is(th,td){padding:var(--aha-space-16) var(--aha-space-8)}
  .aha-comparison__column-name{font-size:var(--aha-size-default)}
  .aha-comparison__column-text{display:none}
  .aha-comparison__table tbody tr:not(.aha-comparison__group) :is(th,td){padding:var(--aha-space-8);font-size:var(--aha-size-sm)}
  .aha-comparison__group th{padding:var(--aha-space-16) var(--aha-space-8) var(--aha-space-8)}
  .aha-comparison--scroll .aha-comparison__table-wrap{/* ds-lint-allow: overflow-x-scroll (four or five compared columns scroll sideways on a phone, with the feature column held in place) */overflow-x:auto}
  .aha-comparison--scroll .aha-comparison__label-col{width:calc(var(--aha-space-96) + var(--aha-space-64))}
  .aha-comparison--scroll .aha-comparison__table :is(thead td:first-child,tbody th[scope="row"]){position:sticky;left:0;z-index:1;background:var(--aha-white);box-shadow:inset -1px 0 0 var(--aha-border-default)}
  .aha-comparison--scroll .aha-comparison__group-label{position:sticky;left:var(--aha-space-8)}
  .aha-comparison--scroll .aha-comparison__table tbody tr:not(.aha-comparison__group):hover th[scope="row"]{background:var(--aha-gray-30)}
}
@container aha-comparison (max-width:479px){
  .aha-comparison__inner{--aha-web-gutter:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-web-gutter)}
  .aha-comparison__cta{margin-top:var(--aha-space-32)}
  .aha-comparison__column-head aha-tag{display:none}
}
